50	/**
51	 * Where this server will look.
52	 *
53	 * The work tree, and the shared workspace. The official server was given the work tree
54	 * alone, so `/tmp/atomaton-workspace` was reachable from the shell and from nothing
55	 * else — while the prompt template told every agent it was "an ordinary directory, on
56	 * the same filesystem, at the same path for every tool". That sentence is true now.
57	 */
58	const ROOTS = [resolve(process.cwd()), WORKSPACE_PATH];
59	
60	/** Lines returned by one `read` when the caller does not say. */
61	const DEFAULT_READ_LINES = 400;
62	
63	/** Matching lines reported by one `grep` when the caller does not say. */
64	const DEFAULT_MAX_MATCHES = 60;
65	
66	/**
67	 * A path inside one of the roots, or an error naming what is allowed.
68	 *
69	 * Resolved before comparing, so `../` cannot walk out of the tree, and compared with a
70	 * separator appended so that `/tmp/atomaton-workspace-other` does not pass as the
71	 * workspace.
72	 */
73	function within(path: string): string {
74	  const full = isAbsolute(path) ? resolve(path) : resolve(process.cwd(), path);
75	  const inside = ROOTS.some(
76	    (root) => full === root || full.startsWith(root.endsWith(sep) ? root : root + sep),
77	  );
78	  if (!inside) {
79	    throw new Error(
80	      `'${path}' is outside the directories this tool can reach. They are: ${ROOTS.join(", ")}.`,
81	    );
82	  }
83	  return full;
84	}
85	
86	/** How a path is shown back: relative to the work tree when it is inside it. */
87	function shown(full: string): string {
88	  const rel = relative(process.cwd(), full);
89	  return rel && !rel.startsWith("..") ? rel.split(sep).join("/") : full;
90	}
