1	/**
2	 * mock-llm-server.ts — a minimal OpenAI-compatible `/chat/completions` HTTP
3	 * server for E2E tests.
4	 *
5	 * The real `atoma` binary's OpenAI client (`OPENAI_BASE_URL` env var) is
6	 * pointed at this server, so the *actual* agent inference loop runs
7	 * unmodified -- only the LLM's decisions are canned/scripted, via a queue of
8	 * responses returned in order, one per HTTP request received.
9	 *
10	 * It answers with Server-Sent Events, not a single JSON body.
11	 *
12	 * That is not a detail of style. Every OpenAI-compatible provider atoma calls goes
13	 * through its *streaming* path (`chat_completion_streaming`): the body carries
14	 * `stream: true`, the repetition circuit breaker watches the deltas as they arrive,
15	 * and the reply is rebuilt from `choices[0].delta` chunks by `StreamAccumulator`. A
16	 * plain JSON body is not read as a reply at all -- `read_sse` looks for `data:` lines,
17	 * finds none, and the accumulator ends up empty. The run then reports "LLM returned
18	 * empty response" and re-asks, which spends the whole queue on the first intended
19	 * step and ends in a 500.
20	 *
21	 * That is what this file used to do, and it made five of the eight e2e tests fail the
22	 * first time the suite ever ran in CI (`atomaton-tools`, PR #100). The failure read as
23	 * the mock running out of canned responses; it was the mock answering in a dialect
24	 * nothing was reading.
25	 */
26	
27	export interface QueuedToolCall {
28	  id: string;
29	  /**
30	   * The name the model calls the tool by. Write `advertised:<suffix>` to defer to
31	   * the binary: the server substitutes the function the request's own tools list
32	   * advertises whose name ends with `<suffix>`, which is what a model that read
33	   * the list would call. A spelled-out name is left alone, for tests that mean a
34	   * specific name to be exact.
35	   */
36	  name: string;
37	  arguments: Record<string, unknown>;
38	}
39	
40	export interface QueuedResponse {
41	  /** Assistant text content. Omit when returning tool_calls. */
42	  content?: string;
43	  toolCalls?: QueuedToolCall[];
44	}
45	
46	export interface MockLlmServer {
47	  url: string;
48	  /** Raw JSON bodies of every request received so far, in order. */
49	  requests: {
50	    messages: { role: string; content?: unknown }[];
51	    tools?: { function?: { name?: string } }[];
52	  }[];
53	  stop(): void;
54	}
55	
56	export function startMockLlmServer(responses: QueuedResponse[]): MockLlmServer {
57	  const queue = [...responses];
58	  const requests: MockLlmServer["requests"] = [];
59	
60	  const server = Bun.serve({
61	    port: 0,
62	    async fetch(req) {
63	      if (req.method !== "POST" || !req.url.endsWith("/chat/completions")) {
64	        return new Response("not found", { status: 404 });
65	      }
66	      const request = (await req.json()) as MockLlmServer["requests"][number];
67	      requests.push(request);
68	
69	      const next = queue.shift();
70	      if (!next) {
71	        return Response.json({ error: { message: "mock-llm-server: no more queued responses" } }, { status: 500 });
72	      }
73	
74	      // Resolve `advertised:<suffix>` names against the request that produced them.
75	      // A call named this way is scripted before the request exists, so the
76	      // substitution happens here, where the tools list is in hand.
77	      const toolCalls = next.toolCalls?.map((tc) => {
78	        const [verb, suffix] = tc.name.split(":");
79	        if (verb !== "advertised" || suffix === undefined) return tc;
80	        const found = request.tools
81	          ?.map((tool) => tool.function?.name ?? "")
82	          .find((name) => name.endsWith(suffix));
83	        return found ? { ...tc, name: found } : tc;
84	      });
85	
86	      // One chunk carrying the whole step, because that is what the tests script: what
87	      // is being exercised is the inference loop and the tool boundary, not chunk
88	      // reassembly, which has its own unit tests in the core. The fields are the same
89	      // ones the non-streaming message would carry, inside the `delta` object the
90	      // accumulator folds in.
91	      const delta = toolCalls
92	        ? {
93	            role: "assistant",
94	            content: null,
95	            tool_calls: toolCalls.map((tc, index) => ({
96	              index,
97	              id: tc.id,
98	              type: "function",
99	              function: { name: tc.name, arguments: JSON.stringify(tc.arguments) },
100	            })),
101	          }
102	        : { role: "assistant", content: next.content ?? "" };
103	
104	      const chunks = [
105	        // The step itself. `finish_reason: null` because the chunk carrying the reason
106	        // is a separate one, which is how providers read here send it.
107	        JSON.stringify({ choices: [{ index: 0, delta, finish_reason: null }] }),
108	        // The terminating chunk: the reason, and no content. `include_usage` is asked
109	        // for on this path, so usage rides the chunk that carries the reason.
110	        JSON.stringify({
111	          choices: [{ index: 0, delta: {}, finish_reason: next.toolCalls ? "tool_calls" : "stop" }],
112	          usage: { prompt_tokens: 1, completion_tokens: 1, total_tokens: 2 },
113	        }),
114	      ];
115	
116	      // `[DONE]` is OpenAI's end-of-stream marker: `sse_data` reports it as no payload,
117	      // which is what stops the reader.
118	      const body = `${chunks.map((chunk) => `data: ${chunk}\n\n`).join("")}data: [DONE]\n\n`;
119	
120	      return new Response(body, {
121	        headers: { "content-type": "text/event-stream", "cache-control": "no-cache" },
122	      });
123	    },
124	  });
125	
126	  return {
127	    url: `http://localhost:${server.port}/v1`,
128	    requests,
129	    stop: () => server.stop(true),
130	  };
131	}

